const nw = msg.data.new_state;
const ow = msg.data.old_state;

if (!nw || !ow || !ow.attributes || !ow.attributes.lekcje) return null;

const newLekcje = nw.attributes.lekcje || [];
const oldLekcje = ow.attributes.lekcje || [];

let imie = "Dziecko";
const fn = nw.attributes.friendly_name || "";
if (fn.includes(": ")) {
    imie = fn.split(': ').pop();
}

const now = new Date();
const today = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`; // czas lokalny, nie UTC

const statusMap = {
    "ODWOL": "ODWOŁANA ❌",
    "ZAST": "ZASTĘPSTWO 🔁",
    "PRZEN": "PRZENIESIONA 🕒",
    "NIEOB": "NIEOBECNI (Wycieczka/Wyjście) 🚌"
};

let alerty = [];

// Przy zmianie tygodnia _curr dostaje tydzień, który _next już zgłosił.
const pominNowyTydzien = nw.entity_id.endsWith('_curr');
const stareDni = new Set(oldLekcje.map(x => x.d));

newLekcje.forEach(n => {
    // WLASNE = własne zajęcia z kalendarza HA, nie zmiana w dzienniku
    if (n.d < today || n.st === "" || n.st === "WLASNE") return;
    const o = oldLekcje.find(x => x.d === n.d && x.g === n.g && x.p === n.p);

    if (o && n.st === o.st) return;                               // bez zmian
    if (!o && pominNowyTydzien && !stareDni.has(n.d)) return;     // już zgłoszone przez _next

    // Nowa pozycja ze statusem (np. zastępstwo z innym przedmiotem) też jest zmianą.
    const statusOpis = statusMap[n.st] || n.st;
    alerty.push(`📅 ${n.d} | ⏰ ${n.g}\n📖 **${n.p}**\nStatus: ${statusOpis}`);
});

if (alerty.length > 0) {
    msg.payload = {
        data: {
            title: `Zmiana planu: ${imie} 📅`,
            message: `Wykryto zmiany w harmonogramie:\n\n${alerty.join('\n\n')}`,
            notification_id: "vultron_plan_alert_" + nw.entity_id.replace(/\./g, '_') + "_" + Date.now()
        }
    };
    return msg;
}

return null;
